@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:resource-tests;MODE=MySQL;DB_CLOSE_DELAY=-1","app.assignments.max-file-bytes=4096","app.exams.expiry-enabled=false"})
@AutoConfigureMockMvc @DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
class ResourceManagementTests {
 static final Path root;static{try{root=Files.createTempDirectory("eduflow-resource-tests-");}catch(IOException e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void storage(DynamicPropertyRegistry p){p.add("app.assignments.storage-dir",()->root.toString());}
 @Autowired MockMvc mvc;@Autowired ObjectMapper mapper;@Autowired JwtService jwt;
 @Autowired UserRepository users;@Autowired StudentRepository students;@Autowired TeacherRepository teachers;@Autowired CourseRepository courses;@Autowired BatchRepository batches;@Autowired BatchEnrollmentRepository enrollments;@Autowired BatchTeacherAssignmentRepository assignments;
 @Autowired ResourceCategoryRepository categories;@Autowired ResourceFolderRepository folders;@Autowired StudyMaterialRepository materials;
 @MockitoSpyBean StudyMaterialVersionRepository versions;@Autowired AssignmentFileStorage storage;
 String admin,teacher,student,other,parent,unassigned;Long course,batch,category,studentId;
 @BeforeEach void setup(){
  admin=account("admin",Role.ADMIN);teacher=account("teacher",Role.TEACHER);unassigned=account("unassigned",Role.TEACHER);student=account("student",Role.STUDENT);other=account("other",Role.STUDENT);parent=account("parent",Role.PARENT);
  var c=new Course();c.setName("Physics");c.setCode("RESOURCE");c.setDurationWeeks(12);course=courses.saveAndFlush(c).getId();
  var b=new Batch();b.setName("Morning");b.setCode("RESOURCE");b.setCourse(c);b.setCapacity(20);b.setStartDate(LocalDate.now().minusDays(10));b.setEndDate(LocalDate.now().plusMonths(3));b.setStatus(BatchStatus.ACTIVE);batch=batches.saveAndFlush(b).getId();
  var t=new Teacher();t.setFullName("Faculty");t.setEmployeeId("RESOURCE");t.setEmail("faculty@resource.test");t.setUser(users.findByEmail("teacher@resource.test").orElseThrow());teachers.saveAndFlush(t);
  var ta=new BatchTeacherAssignment();ta.setBatch(b);ta.setTeacher(t);assignments.saveAndFlush(ta);
  var s=new Student("RESOURCE");s.setFullName("Learner");s.setEmail("admission@resource.test");s.setPhone("9876543210");s.setDateOfBirth(LocalDate.of(2008,1,1));s.setAdmissionDate(LocalDate.now().minusDays(10));s.setGuardianName("Guardian");s.setGuardianPhone("9876543211");s.setAddress("School");s.setUser(users.findByEmail("student@resource.test").orElseThrow());studentId=students.saveAndFlush(s).getId();
  var n=new BatchEnrollment();n.setBatch(b);n.setStudent(s);n.setEnrollmentDate(LocalDate.now().minusDays(5));enrollments.saveAndFlush(n);
  var cat=new ResourceCategory();cat.setName("Notes");cat.setNormalizedName("notes");category=categories.saveAndFlush(cat).getId();
 }
 String account(String name,Role role){var u=users.saveAndFlush(new User(name,name+"@resource.test","unused",role));return jwt.generateToken(u.getEmail());}
 @AfterEach void clean()throws Exception{versions.deleteAll();materials.deleteAll();for(var f:folders.findAll()){f.setParentFolder(null);folders.saveAndFlush(f);}folders.deleteAll();categories.deleteAll();assignments.deleteAll();enrollments.deleteAll();teachers.deleteAll();students.deleteAll();batches.deleteAll();courses.deleteAll();users.deleteAll();try(var files=Files.list(root)){for(var file:files.toList())Files.delete(file);}}
 MockHttpServletRequestBuilder json(MockHttpServletRequestBuilder b,Object value,String token)throws Exception{return b.header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(value));}
 JsonNode body(MvcResult r)throws Exception{return mapper.readTree(r.getResponse().getContentAsString());}
 Map<String,Object> input(String title,String type){return new HashMap<>(Map.of("title",title,"description","Chapter notes","courseId",course,"batchId",batch,"categoryId",category,"resourceType",type));}
 JsonNode create(String title)throws Exception{return body(mvc.perform(json(post("/api/resources/materials"),input(title,"DOCUMENT"),teacher)).andExpect(status().isCreated()).andReturn());}
 JsonNode getMaterial(long id)throws Exception{return body(mvc.perform(get("/api/resources/materials/"+id).header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andReturn());}
 long version(long id)throws Exception{return getMaterial(id).get("version").asLong();}
 byte[] pdf()throws Exception{try(var doc=new PDDocument();var out=new ByteArrayOutputStream()){doc.addPage(new PDPage());doc.save(out);return out.toByteArray();}}
 MockMultipartFile file(String name,byte[] bytes){return new MockMultipartFile("file",name,"application/octet-stream",bytes);}
 JsonNode upload(long id,String name,byte[] bytes)throws Exception{return body(mvc.perform(multipart("/api/resources/materials/"+id+"/versions").file(file(name,bytes)).param("version",Long.toString(version(id))).header("Authorization","Bearer "+teacher)).andExpect(status().isOk()).andReturn());}
 JsonNode publish(long id)throws Exception{return body(mvc.perform(json(post("/api/resources/materials/"+id+"/publish"),Map.of("version",version(id)),teacher)).andExpect(status().isOk()).andReturn());}
 long published()throws Exception{long id=create("Notes").get("id").asLong();upload(id,"notes.pdf",pdf());publish(id);return id;}
 JsonNode folder(String name,Long parentId)throws Exception{var data=new HashMap<String,Object>(Map.of("name",name,"courseId",course,"batchId",batch));if(parentId!=null)data.put("parentFolderId",parentId);return body(mvc.perform(json(post("/api/resources/folders"),data,teacher)).andExpect(status().isCreated()).andReturn());}
 @Test void categoryNamesAreNormalizedCaseInsensitively()throws Exception{mvc.perform(json(post("/api/resources/categories"),Map.of("name","  nOtEs  "),admin)).andExpect(status().isConflict());mvc.perform(json(post("/api/resources/categories"),Map.of("name","Practice Sheets"),admin)).andExpect(status().isCreated());mvc.perform(json(post("/api/resources/categories"),Map.of("name","private"),teacher)).andExpect(status().isForbidden());}
 @Test void deactivationPreservesPublishedMaterials()throws Exception{long id=published();mvc.perform(patch("/api/resources/categories/"+category+"/deactivate").header("Authorization","Bearer "+admin)).andExpect(status().isOk());mvc.perform(get("/api/resources/materials/"+id).header("Authorization","Bearer "+student)).andExpect(status().isOk()).andExpect(jsonPath("categoryName").value("Notes"));mvc.perform(json(post("/api/resources/materials"),input("New","DOCUMENT"),teacher)).andExpect(status().isBadRequest());}
 @Test void folderCyclesAndNonemptyDeletionAreRejected()throws Exception{var first=folder("Root",null);long rootId=first.get("id").asLong();long child=folder("Child",rootId).get("id").asLong();mvc.perform(json(put("/api/resources/folders/"+rootId),Map.of("name","Root","courseId",course,"batchId",batch,"parentFolderId",child),teacher)).andExpect(status().isBadRequest());mvc.perform(delete("/api/resources/folders/"+rootId).header("Authorization","Bearer "+teacher)).andExpect(status().isConflict());mvc.perform(delete("/api/resources/folders/"+child).header("Authorization","Bearer "+teacher)).andExpect(status().isNoContent());}
 @Test void folderScopeCannotBeBroadenedOrLinkedAcrossScopes()throws Exception{long f=folder("Batch notes",null).get("id").asLong();mvc.perform(json(put("/api/resources/folders/"+f),Map.of("name","Unsafe","courseId",course),admin)).andExpect(status().isConflict());mvc.perform(json(post("/api/resources/folders"),Map.of("name","Wide","courseId",course,"parentFolderId",f),admin)).andExpect(status().isBadRequest());for(String token:List.of(other,unassigned,parent))mvc.perform(get("/api/resources/folders/"+f).header("Authorization","Bearer "+token)).andExpect(status().isForbidden());}
 @Test void folderDeletionPreservesAttachedMaterial()throws Exception{long f=folder("Notes",null).get("id").asLong();var i=input("Folder notes","DOCUMENT");i.put("folderId",f);mvc.perform(json(post("/api/resources/materials"),i,teacher)).andExpect(status().isCreated());mvc.perform(delete("/api/resources/folders/"+f).header("Authorization","Bearer "+teacher)).andExpect(status().isConflict());}
 @Test void invalidCourseBatchCombinationIsRejected()throws Exception{var c=new Course();c.setName("Other");c.setCode("OTHER");c.setDurationWeeks(10);long id=courses.saveAndFlush(c).getId();var i=input("Invalid","DOCUMENT");i.put("courseId",id);mvc.perform(json(post("/api/resources/materials"),i,admin)).andExpect(status().isBadRequest());mvc.perform(json(post("/api/resources/folders"),Map.of("name","Wrong","courseId",id,"batchId",batch),admin)).andExpect(status().isBadRequest());}
 @Test void onlyAssignedStaffCanCreateAndDraftsAreHidden()throws Exception{for(String token:List.of(unassigned,student,parent))mvc.perform(json(post("/api/resources/materials"),input("Denied","DOCUMENT"),token)).andExpect(status().isForbidden());long id=create("Draft").get("id").asLong();mvc.perform(get("/api/resources/materials").header("Authorization","Bearer "+student)).andExpect(jsonPath("totalElements").value(0));mvc.perform(get("/api/resources/materials/"+id).header("Authorization","Bearer "+student)).andExpect(status().isForbidden());mvc.perform(get("/api/resources/materials")).andExpect(status().isUnauthorized());}
 @Test void teacherCannotManageCourseWideResources()throws Exception{var i=input("Course-wide","LINK");i.remove("batchId");i.put("externalUrl","https://example.org/notes");mvc.perform(json(post("/api/resources/materials"),i,teacher)).andExpect(status().isForbidden());long id=body(mvc.perform(json(post("/api/resources/materials"),i,admin)).andExpect(status().isCreated()).andReturn()).get("id").asLong();mvc.perform(json(post("/api/resources/materials/"+id+"/publish"),Map.of("version",version(id)),admin)).andExpect(status().isOk());mvc.perform(get("/api/resources/materials/"+id).header("Authorization","Bearer "+student)).andExpect(status().isOk());mvc.perform(get("/api/resources/materials").header("Authorization","Bearer "+student)).andExpect(jsonPath("totalElements").value(1));}
 @Test void publicationRequiresFileAndValidTransitions()throws Exception{long id=create("Draft").get("id").asLong();mvc.perform(json(post("/api/resources/materials/"+id+"/publish"),Map.of("version",version(id)),admin)).andExpect(status().isConflict());mvc.perform(json(post("/api/resources/materials/"+id+"/archive"),Map.of("version",version(id)),admin)).andExpect(status().isConflict());upload(id,"notes.pdf",pdf());publish(id);mvc.perform(json(post("/api/resources/materials/"+id+"/publish"),Map.of("version",version(id)),admin)).andExpect(status().isConflict());mvc.perform(json(post("/api/resources/materials/"+id+"/archive"),Map.of("version",version(id)),admin)).andExpect(status().isOk());mvc.perform(get("/api/resources/materials/"+id).header("Authorization","Bearer "+student)).andExpect(status().isForbidden());mvc.perform(json(post("/api/resources/materials/"+id+"/publish"),Map.of("version",version(id)),admin)).andExpect(status().isConflict());}
 @Test void stagedVersionsPreservePublishedStudentFile()throws Exception{long id=published();upload(id,"replacement.txt","new text".getBytes());mvc.perform(get("/api/resources/materials/"+id).header("Authorization","Bearer "+student)).andExpect(jsonPath("currentVersion").value(1)).andExpect(jsonPath("file.originalFileName").value("notes.pdf"));mvc.perform(get("/api/resources/materials/"+id+"/download").header("Authorization","Bearer "+student)).andExpect(content().contentType("application/pdf"));publish(id);mvc.perform(get("/api/resources/materials/"+id+"/download").header("Authorization","Bearer "+student)).andExpect(content().contentType("text/plain"));assertThat(versions.count()).isEqualTo(2);}
 @Test void publishedMetadataAndHistoricalFilesAreProtected()throws Exception{long id=published();var i=input("Changed","DOCUMENT");i.put("version",version(id));mvc.perform(json(put("/api/resources/materials/"+id),i,admin)).andExpect(status().isConflict());long vid=versions.findAll().getFirst().getId();mvc.perform(get("/api/resources/materials/"+id+"/versions/"+vid+"/download").header("Authorization","Bearer "+teacher)).andExpect(status().isOk());mvc.perform(get("/api/resources/materials/"+id+"/versions/"+vid+"/download").header("Authorization","Bearer "+student)).andExpect(status().isForbidden());}
 @Test void binaryAccessAndPreviewEnforceOwnership()throws Exception{long id=published();for(String token:List.of(other,unassigned,parent))for(String suffix:List.of("/download","/preview","/versions"))mvc.perform(get("/api/resources/materials/"+id+suffix).header("Authorization","Bearer "+token)).andExpect(status().isForbidden());mvc.perform(get("/api/resources/materials/"+id+"/preview").header("Authorization","Bearer "+student)).andExpect(status().isOk()).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(header().string("Content-Disposition",org.hamcrest.Matchers.startsWith("inline")));}
 @Test void currentEnrollmentRequiredAndWithdrawnStudentsLoseAccess()throws Exception{long id=published();var n=enrollments.findAll().getFirst();n.setStatus(EnrollmentStatus.WITHDRAWN);n.setWithdrawalDate(LocalDate.now());enrollments.saveAndFlush(n);mvc.perform(get("/api/resources/materials/"+id).header("Authorization","Bearer "+student)).andExpect(status().isForbidden());mvc.perform(get("/api/resources/materials").header("Authorization","Bearer "+student)).andExpect(jsonPath("totalElements").value(0));}
 @Test void filtersStatisticsAndOptionsAreScoped()throws Exception{published();create("Other draft");mvc.perform(get("/api/resources/materials").param("courseId",course.toString()).param("batchId",batch.toString()).param("search","notes").param("size","1").header("Authorization","Bearer "+student)).andExpect(jsonPath("totalElements").value(1));mvc.perform(get("/api/resources/stats").header("Authorization","Bearer "+teacher)).andExpect(status().isOk()).andExpect(jsonPath("totalMaterials").value(2)).andExpect(jsonPath("publishedMaterials").value(1)).andExpect(jsonPath("draftMaterials").value(1)).andExpect(jsonPath("courses[0].count").value(2));mvc.perform(get("/api/resources/stats").header("Authorization","Bearer "+student)).andExpect(jsonPath("totalMaterials").value(1)).andExpect(jsonPath("draftMaterials").value(0));mvc.perform(get("/api/resources/options").header("Authorization","Bearer "+other)).andExpect(jsonPath("batches").isEmpty());}
 @Test void unsafeUrlsAndDuplicateTitlesAreRejected()throws Exception{for(String url:List.of("javascript:alert(1)","file:///secret","https://user:pass@example.org/","//example.org","data:text/html,code")){var i=input("Link","LINK");i.put("externalUrl",url);mvc.perform(json(post("/api/resources/materials"),i,teacher)).andExpect(status().isBadRequest());}create("Unique");mvc.perform(json(post("/api/resources/materials"),input("UNIQUE","DOCUMENT"),teacher)).andExpect(status().isConflict());}
 @Test void rejectsSpoofingTraversalSizeAndMime()throws Exception{long id=create("Uploads").get("id").asLong();for(var f:List.of(file("../secret.pdf",pdf()),file("fake.pdf","bad".getBytes()),file("code.exe",new byte[]{1}),file("text.txt",new byte[]{0,1}),new MockMultipartFile("file","notes.pdf","text/plain",pdf())))mvc.perform(multipart("/api/resources/materials/"+id+"/versions").file(f).param("version",Long.toString(version(id))).header("Authorization","Bearer "+admin)).andExpect(status().isBadRequest());mvc.perform(multipart("/api/resources/materials/"+id+"/versions").file(file("huge.txt",new byte[4097])).param("version",Long.toString(version(id))).header("Authorization","Bearer "+admin)).andExpect(status().isPayloadTooLarge());assertThatThrownBy(()->storage.read("../escape")).isInstanceOf(IllegalArgumentException.class);assertThat(versions.count()).isZero();}
 @Test void failedDatabaseUploadCleansPrivateFile()throws Exception{long id=create("Rollback").get("id").asLong();doThrow(new org.springframework.dao.DataIntegrityViolationException("test")).when(versions).saveAndFlush(any(StudyMaterialVersion.class));mvc.perform(multipart("/api/resources/materials/"+id+"/versions").file(file("notes.pdf",pdf())).param("version",Long.toString(version(id))).header("Authorization","Bearer "+admin)).andExpect(status().isConflict());reset(versions);assertThat(versions.count()).isZero();try(var entries=Files.list(root)){assertThat(entries.count()).isZero();}}
 @Test void concurrentVersionUploadsRejectStaleWriter()throws Exception{long id=create("Concurrent").get("id").asLong();long expected=version(id);byte[] pdf=pdf();var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){Callable<Integer> request=()->{start.await();return mvc.perform(multipart("/api/resources/materials/"+id+"/versions").file(file("notes.pdf",pdf)).param("version",Long.toString(expected)).header("Authorization","Bearer "+teacher)).andReturn().getResponse().getStatus();};var one=pool.submit(request);var two=pool.submit(request);start.countDown();assertThat(List.of(one.get(20,TimeUnit.SECONDS),two.get(20,TimeUnit.SECONDS))).containsExactlyInAnyOrder(200,409);}assertThat(versions.count()).isEqualTo(1);}
 byte[] office(String ext,boolean unsafe)throws Exception{String main=ext.equals("pptx")?"ppt/presentation.xml":"xl/workbook.xml",rootName=ext.equals("pptx")?"presentation":"workbook",ns=ext.equals("pptx")?"presentationml":"spreadsheetml",type=ext.equals("pptx")?"presentationml.presentation":"spreadsheetml.sheet";var parts=new LinkedHashMap<String,String>();parts.put("[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Override PartName=\"/"+main+"\" ContentType=\"application/vnd.openxmlformats-officedocument."+type+".main+xml\"/></Types>");parts.put("_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\""+main+"\""+(unsafe?" TargetMode=\"External\"":"")+"/></Relationships>");parts.put(main,"<r:"+rootName+" xmlns:r=\"http://schemas.openxmlformats.org/"+ns+"/2006/main\"/>");var out=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(out)){for(var e:parts.entrySet()){zip.putNextEntry(new ZipEntry(e.getKey()));zip.write(e.getValue().getBytes());zip.closeEntry();}}return out.toByteArray();}
 @Test void validatesPowerPointAndExcelPackages()throws Exception{var i=input("Slides","PRESENTATION");long slides=body(mvc.perform(json(post("/api/resources/materials"),i,teacher)).andExpect(status().isCreated()).andReturn()).get("id").asLong();upload(slides,"slides.pptx",office("pptx",false));long sheet=create("Worksheet").get("id").asLong();upload(sheet,"practice.xlsx",office("xlsx",false));mvc.perform(multipart("/api/resources/materials/"+sheet+"/versions").file(file("unsafe.xlsx",office("xlsx",true))).param("version",Long.toString(version(sheet))).header("Authorization","Bearer "+teacher)).andExpect(status().isBadRequest());mvc.perform(get("/api/resources/materials/"+sheet+"/preview").header("Authorization","Bearer "+teacher)).andExpect(status().isBadRequest());}
 @Test void atomicCreationDoesNotLeaveDraftOnInvalidFile()throws Exception{mvc.perform(multipart("/api/resources/materials").file(new MockMultipartFile("data","data","application/json",mapper.writeValueAsBytes(input("Bad","DOCUMENT")))).file(file("bad.pdf","invalid".getBytes())).header("Authorization","Bearer "+teacher)).andExpect(status().isBadRequest());assertThat(materials.count()).isZero();}
 @Test void folderSelectorsMatchTheExactMaterialScope()throws Exception{folder("Batch notes",null);mvc.perform(json(post("/api/resources/folders"),Map.of("name","Course notes","courseId",course),admin)).andExpect(status().isCreated());mvc.perform(get("/api/resources/folders").param("courseId",course.toString()).param("courseWideOnly","true").header("Authorization","Bearer "+student)).andExpect(status().isOk()).andExpect(jsonPath("totalElements").value(1)).andExpect(jsonPath("content[0].name").value("Course notes"));}
}
